async function matches(a,b){const e=new TextEncoder();const [x,y]=await Promise.all([crypto.subtle.digest('SHA-256',e.encode(a)),crypto.subtle.digest('SHA-256',e.encode(b))]);const xx=new Uint8Array(x),yy=new Uint8Array(y);let d=0;for(let i=0;i<xx.length;i++)d|=xx[i]^yy[i];return d===0}
